; ============================================================
; NTC program - generated by NTC BASIC (VB style BASIC to NTC)
; platform: cpc (Amstrad CPC - direct hardware, no firmware), starts in normal mode
; ============================================================

			DEVICE AMSTRADCPC6128		; for SAVEAMSDOS at the end
			org #0040

NTC_TERM	equ 0		; Option Terminal: 0 none, 1 VT52, 2 ANSI (CP/M)
NTC_STRMAX	equ 255		; the longest string (library buffers, temps)
NTC_MEMBANKS	equ 64		; Option Memory: the most 64K banks the Memory class looks for
NTC_ROMENABLE	equ 0		; Option RomEnable (cpcfw, cpcmin): the start code starts the ROMs
NTC_ROMLIB	equ 1		; 1 = the library is the keyword ROM (Library: ROM; ntcRomAsm builds it)

ntc_start:
			di
			call ntc_rj_find		; Library: ROM - find the ROM, patch the jump block
			jr nc, ntc_rj_ok
			ei
			ret				; no ROM (the message is shown): back to the caller
ntc_rj_ok:
			di				; (KL ROM SELECT lets interrupts in again)
			ld hl, ntc_rj_exit
			push hl			; End comes back here: the caller's ROM selection again
			ld (ntc_csp), sp
			ld a, 1
			ld (ntc_nmode), a		; normal mode: waits let interrupts in
			ld ix, ntc_go
			jp ntc_plat_irqon		; interrupt handler for normal mode
ntc_go:
			ld sp, main_thread
			ret

; ============================================================
; Main Thread
; ============================================================

main_thread:
			dw kw_scrinit		; mode 1, ROMs off, clear screen
			dw kw_bssinit, ntc_bss, ntc_bss_size		; the arrays: do they fit, clear them

			; 20: Print "VB test 3"
			dw kw_printzoscii
			dw glyph_56, glyph_42, glyph_20, glyph_74, glyph_65, glyph_73, glyph_74, glyph_20
			dw glyph_33, 1, 0		; "VB test 3\n"

			; 21: Chk Red, 0
			dw p_chk_c, lit_0, lit_0

			; 22: Chk Green, 5
			dw p_chk_c, lit_5, lit_5

			; 23: Chk Blue, 6
			dw p_chk_c, lit_6, lit_6

			; 24: Chk Colour.Blue + Size.Large, 16
			dw p_chk_c, lit_16, lit_16

			; 25: c = Green
			dw kw_ltov, 5, var_c

			; 26: Chk c, 5
			dw p_chk_c, var_c, lit_5

			; 28: .w = 3
			dw kw_ltov, 3, var_b_w

			; 29: .h = 4
			dw kw_ltov, 4, var_b_h

			; 30: .label = "box"
			dw kw_strcpy, var_b_label, str0

			; 31: n = .w * .h
			dw kw_mulvv, var_b_w, var_b_h, var_n

			; 33: Chk n, 12
			dw p_chk_c, var_n, lit_12

			; 34: ChkS b.label, "box"
			dw p_chks_c, var_b_label, str0

			; 35: For i = 0 To 2
			dw kw_ztov, var_i
for1_t:

			; 37: .w = i
			dw kw_aset, arr_boxes_w, var_i, var_i

			; 38: .h = i * 2
			dw kw_2x, var_i, tmp1
			dw kw_aset, arr_boxes_h, var_i, tmp1

			; 40: Next
			dw kw_next1l_n, var_i, 2, for1_t
for1_e:

			; 41: Chk boxes(2).w + boxes(2).h, 6
			dw kw_add, arr_boxes_w+4, arr_boxes_h+4, tmp0
			dw p_chk_c, tmp0, lit_6

			; 42: n = 0
			dw kw_ztov, var_n

			; 43: For i = 1 To 3
			dw kw_ltov, 1, var_i
for2_t:

			; 44: On i GoSub one, two, three
			dw kw_cpeqvl, var_i, 1
			dw kw_goto_iffalse_n, on3_0
			dw lbl_one_gs
			dw on3_e_go
on3_0:
			dw kw_cpeqvl, var_i, 2
			dw kw_goto_iffalse_n, on3_1
			dw lbl_two_gs
			dw on3_e_go
on3_1:
			dw kw_cpeqvl, var_i, 3
			dw kw_goto_iffalse_n, on3_2
			dw lbl_three_gs
on3_2:
on3_e:

			; 45: Next
			dw kw_next1l_n, var_i, 3, for2_t
for2_e:

			; 46: Chk n, 321
			dw p_chk_c, var_n, lit_321

			; 47: i = 2
			dw kw_ltov, 2, var_i

			; 48: On i GoTo l1, l2
			dw kw_cpeqvl, var_i, 1
			dw kw_goto_iftrue_n, lbl_l1
			dw kw_cpeqvl, var_i, 2
			dw kw_goto_iftrue_n, lbl_l2

			; 49: Chk 0, 1
			dw p_chk_c, lit_0, lit_1

			; 50: l1:
lbl_l1:

			; 51: Chk 0, 1
			dw p_chk_c, lit_0, lit_1

			; 52: l2:
lbl_l2:

			; 53: Chk 1, 1
			dw p_chk_c, lit_1, lit_1

			; 54: k = Inkey$
			dw kw_inkeys, stmp0
			dw kw_strcpy, var_k, stmp0

			; 55: ChkS k, ""
			dw p_chks_c, var_k, str1

			; 56: Print
			dw kw_printnl

			; 57: Print t; " tests, "; bad; " failed"
			dw kw_printint, var_t
			dw kw_printzoscii
			dw glyph_20, glyph_74, glyph_65, glyph_73, glyph_74, glyph_73, glyph_2C, glyph_20
			dw 0		; " tests, "
			dw kw_printint, var_bad
			dw kw_printzoscii
			dw glyph_20, glyph_66, glyph_61, glyph_69, glyph_6C, glyph_65, glyph_64, 1
			dw 0		; " failed\n"

			; 58: Print "Press a key";
			dw kw_printzoscii
			dw glyph_50, glyph_72, glyph_65, glyph_73, glyph_73, glyph_20, glyph_61, glyph_20
			dw glyph_6B, glyph_65, glyph_79, 0		; "Press a key"

			; 59: Do : Frame : Loop Until Inkey <> 0
do5_t:
			dw kw_frame
			dw kw_inkey, tmp0
			dw kw_cpnevl, tmp0, 0
			dw kw_goto_iffalse_n, do5_t
do5_e:

			; 60: Print
			dw kw_printnl

			; 61: End
			dw kw_stop

			; 62: one:
lbl_one:

			; 63: n = n + 1
			dw kw_inc, var_n

			; 64: Return
			dw lbl_one_rt

			; 65: two:
lbl_two:

			; 66: n = n + 20
			dw kw_addl, var_n, 20, var_n

			; 67: Return
			dw lbl_two_rt

			; 68: three:
lbl_three:

			; 69: n = n + 300
			dw kw_addl, var_n, 300, var_n

			; 70: Return
			dw lbl_three_rt

; ============================================================
; sub chk (normal mode)
; ============================================================

p_chk:

			; 73: t = t + 1
			dw kw_inc, var_t

			; 74: Print t; ":";
			dw kw_printint, var_t
			dw kw_printzoscii
			dw glyph_3A, 0		; ":"

			; 75: If got = want Then Print "ok "; Else Print "FAIL("; got; ") "; : bad = bad + 1
			dw kw_cpeqvv, var_chk_got, var_chk_want
			dw kw_goto_iffalse_n, if6_1
			dw kw_printzoscii
			dw glyph_6F, glyph_6B, glyph_20, 0		; "ok "
			dw if6_e_go
if6_1:
			dw kw_printzoscii
			dw glyph_46, glyph_41, glyph_49, glyph_4C, glyph_28, 0		; "FAIL("
			dw kw_printint, var_chk_got
			dw kw_printzoscii
			dw glyph_29, glyph_20, 0		; ") "
			dw kw_inc, var_bad
if6_e:
			dw p_chk_r

; ============================================================
; sub chks (normal mode)
; ============================================================

p_chks:

			; 79: t = t + 1
			dw kw_inc, var_t

			; 80: Print t; ":";
			dw kw_printint, var_t
			dw kw_printzoscii
			dw glyph_3A, 0		; ":"

			; 81: If got = want Then Print "ok "; Else Print "FAIL["; got; "] "; : bad = bad + 1
			dw kw_strcmpeq, var_chks_got, var_chks_want
			dw kw_goto_iffalse_n, if7_1
			dw kw_printzoscii
			dw glyph_6F, glyph_6B, glyph_20, 0		; "ok "
			dw if7_e_go
if7_1:
			dw kw_printzoscii
			dw glyph_46, glyph_41, glyph_49, glyph_4C, glyph_5B, 0		; "FAIL["
			dw kw_printstrvar, var_chks_got
			dw kw_printzoscii
			dw glyph_5D, glyph_20, 0		; "] "
			dw kw_inc, var_bad
if7_e:
			dw p_chks_r

; ============================================================
; Jump stubs (code, ROMable)
;   label_go: GOTO label
;   label_gs: GOSUB label, return point -> label_rs (RAM)
;   label_rt: RETURN from label
;   p_name_c: call a procedure, p_name_r: end of it
;   turbo mode ends with ret, normal mode with jp ntc_xn
; ============================================================

on3_e_go:			ld sp, on3_e
			jp ntc_xn
if6_e_go:			ld sp, if6_e
			jp ntc_xn
if7_e_go:			ld sp, if7_e
			jp ntc_xn
lbl_one_gs:			ld (lbl_one_rs), sp
			ld sp, lbl_one
			jp ntc_xn
lbl_one_rt:			ld sp, (lbl_one_rs)
			jp ntc_xn
lbl_two_gs:			ld (lbl_two_rs), sp
			ld sp, lbl_two
			jp ntc_xn
lbl_two_rt:			ld sp, (lbl_two_rs)
			jp ntc_xn
lbl_three_gs:			ld (lbl_three_rs), sp
			ld sp, lbl_three
			jp ntc_xn
lbl_three_rt:			ld sp, (lbl_three_rs)
			jp ntc_xn

p_chk_c:		; call chk (normal)
			pop hl			; got
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_chk_got), de
			pop hl			; want
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_chk_want), de
			ld (p_chk_rs), sp
			ld sp, p_chk
			jp ntc_xn
p_chk_r:		; end of chk
			ld sp, (p_chk_rs)
			jp ntc_xn
p_chks_c:		; call chks (normal)
			pop hl			; got
			ld de, var_chks_got
			ld b, 255
p_chks_si0:
			ld a, (hl)
			ld (de), a
			or a
			jr z, p_chks_si0_e
			inc hl
			inc de
			djnz p_chks_si0
			xor a
			ld (de), a
p_chks_si0_e:
			pop hl			; want
			ld de, var_chks_want
			ld b, 255
p_chks_si1:
			ld a, (hl)
			ld (de), a
			or a
			jr z, p_chks_si1_e
			inc hl
			inc de
			djnz p_chks_si1
			xor a
			ld (de), a
p_chks_si1_e:
			ld (p_chks_rs), sp
			ld sp, p_chks
			jp ntc_xn
p_chks_r:		; end of chks
			ld sp, (p_chks_rs)
			jp ntc_xn

; ============================================================
; Variables
; ============================================================

var_c:			dw 0
var_b_w:			dw 0
var_b_h:			dw 0
			db 40			; capacity
var_b_label:			ds 41
var_n:			dw 0
var_i:			dw 0
			db 40			; capacity
var_k:			ds 41
var_t:			dw 0
var_bad:			dw 0
p_chk_rs:			dw 0
var_chk_got:			dw 0
var_chk_want:			dw 0
p_chks_rs:			dw 0
			db 255			; capacity
var_chks_got:			ds 256
			db 255			; capacity
var_chks_want:			ds 256
lbl_one_rs:			dw 0
lbl_two_rs:			dw 0
lbl_three_rs:			dw 0
tmp0:			dw 0
tmp1:			dw 0
			db 255			; capacity
stmp0:			ds 256

; numbers passed by address (read only)
lit_0:			dw 0
lit_5:			dw 5
lit_6:			dw 6
lit_16:			dw 16
lit_12:			dw 12
lit_321:			dw 321
lit_1:			dw 1

; ============================================================
; ZOSCII glyphs - each points at its 8 byte bitmap in ntc_font
; ============================================================

glyph_20			equ ntc_font + 0		; " "
glyph_28			equ ntc_font + 64		; "("
glyph_29			equ ntc_font + 72		; ")"
glyph_2C			equ ntc_font + 96		; ","
glyph_33			equ ntc_font + 152		; "3"
glyph_3A			equ ntc_font + 208		; ":"
glyph_41			equ ntc_font + 264		; "A"
glyph_42			equ ntc_font + 272		; "B"
glyph_46			equ ntc_font + 304		; "F"
glyph_49			equ ntc_font + 328		; "I"
glyph_4C			equ ntc_font + 352		; "L"
glyph_50			equ ntc_font + 384		; "P"
glyph_56			equ ntc_font + 432		; "V"
glyph_5B			equ ntc_font + 472		; "["
glyph_5D			equ ntc_font + 488		; "]"
glyph_61			equ ntc_font + 520		; "a"
glyph_64			equ ntc_font + 544		; "d"
glyph_65			equ ntc_font + 552		; "e"
glyph_66			equ ntc_font + 560		; "f"
glyph_69			equ ntc_font + 584		; "i"
glyph_6B			equ ntc_font + 600		; "k"
glyph_6C			equ ntc_font + 608		; "l"
glyph_6F			equ ntc_font + 632		; "o"
glyph_72			equ ntc_font + 656		; "r"
glyph_73			equ ntc_font + 664		; "s"
glyph_74			equ ntc_font + 672		; "t"
glyph_79			equ ntc_font + 712		; "y"

; ============================================================
; Strings
; ============================================================

str0:			db "box", 0
str1:			db 0

; ============================================================
; Keyword library (rom)
; ============================================================

; Library: ROM - the keyword library is in the ROM NTC CPC (NTCCPC.ROM).
; Its routines: this jump block, the numbers made into addresses by the ROM at the start.
; Its variables and constants: fixed addresses (RAM #8800 - #A5EF is the ROM's).
ntc_rj_block:
kw_stop:		jp 1
ntc_xn:		jp 2
kw_goto_iffalse_n:	jp 11
kw_goto_iftrue_n:	jp 13
kw_next1l_n:	jp 31
kw_ltov:		jp 47
kw_ztov:		jp 49
kw_inc:		jp 51
kw_add:		jp 53
kw_addl:		jp 54
kw_2x:		jp 57
kw_mulvv:	jp 60
kw_cpeqvv:	jp 95
kw_cpeqvl:	jp 96
kw_cpnevl:	jp 98
kw_aset:		jp 112
kw_strcpy:	jp 122
kw_strcmpeq:	jp 126
kw_printzoscii:	jp 129
kw_printstrvar:	jp 130
kw_printint:	jp 132
kw_printnl:	jp 139
kw_inkey:	jp 145
kw_inkeys:	jp 146
kw_scrinit:	jp 147
kw_frame:	jp 153
kw_bssinit:	jp 283
ntc_plat_irqon:	jp 308
NTC_RJ_N	equ 28		; entries
ntc_csp	equ #8800		; ROM data
ntc_font	equ #948E		; ROM bss
ntc_nmode	equ #8807		; ROM data
ntc_v_free	equ #88B0		; ROM data
ntc_v_romen	equ #88B6		; ROM data
ntc_v_romold	equ #88B8		; ROM data
ntc_v_stamp	equ #88B4		; ROM data
ntc_v_start	equ #88B2		; ROM data
			ASSERT ntc_free <= #8800, "Library: ROM - the program and its arrays must end below #8800 (the ROM's RAM)"

; the start: find the ROM set in slots 0 - 31 (its main ROM, then the others with the same
; stamp), have the main one patch the jump block. NC = ready; C = not there / too old
; (the message is shown, the caller's ROM selection is back)
ntc_rj_find:
			ld c, 0
			call #B90F		; KL ROM SELECT: B / C = the caller's state and selection
			ld (ntc_rj_old), bc
			xor a
			ld (ntc_rj_want), a
			call ntc_rj_scan		; the main ROM
			jp c, ntc_rj_nf
			ld (ntc_rj_slots), a
			ld e, (hl)
			inc hl
			ld d, (hl)			; its patcher
			ld (ntc_rj_call + 1), de
			ld a, 1
ntc_rj_more:				; the other ROMs of the set
			ld (ntc_rj_want), a
			ld hl, ntc_rj_n
			cp (hl)
			jr nc, ntc_rj_all
			call ntc_rj_scan
			jp c, ntc_rj_part
			ld b, a
			ld a, (ntc_rj_want)
			ld e, a
			ld d, 0
			ld hl, ntc_rj_slots
			add hl, de
			ld (hl), b
			inc a
			jr ntc_rj_more
ntc_rj_all:
			ld a, (ntc_rj_slots)
			ld c, a
			call #B90F		; KL ROM SELECT: the main ROM
			di					; (KL ROM SELECT lets interrupts in)
			ld a, (ntc_rj_slots)	; its slot
			ld hl, ntc_rj_block
			ld bc, NTC_RJ_N
			ld de, ntc_rj_slots
ntc_rj_call:
			call 0				; HL = jump block, BC = entries, A = slot, DE = slots; C: DE = a number it hasn't got
			jp c, ntc_rj_lacks
			ld hl, ntc_free
			ld (ntc_v_free), hl
			ld hl, ntc_start
			ld (ntc_v_start), hl
			ld hl, 0
			ld (ntc_v_stamp), hl
			ld a, 0
			ld (ntc_v_romen), a
			ld a, (ntc_rj_old)
			ld (ntc_v_romold), a
			or a				; NC: ready
			ret
; ntc_rj_scan - a ROM of the set: ROM ntc_rj_want (0 = the main one, any stamp; the others
; with the main one's stamp). NC: A = its slot, HL = past its block's count byte (the main
; one: at its patcher), it is selected. C: not there
ntc_rj_scan:
			ld c, 0
ntc_rj_next:
			push bc
			call #B90F		; KL ROM SELECT: ROM C
			pop bc
			ld a, (#C000)
			cp 1				; a background ROM?
			jr nz, ntc_rj_skip
			ld hl, (#C004)		; its names
			ld a, h
			cp #C0
			jr c, ntc_rj_skip
ntc_rj_name:
			ld a, (hl)
			inc hl
			or a
			jr nz, ntc_rj_name		; to the 0 after the names
			ld de, ntc_rj_sig
			ld b, ntc_rj_sige - ntc_rj_sig
ntc_rj_cmp:
			ld a, (de)
			cp (hl)
			jr nz, ntc_rj_skip
			inc de
			inc hl
			djnz ntc_rj_cmp
			ld e, (hl)
			inc hl
			ld d, (hl)			; DE = its set's stamp
			inc hl
			ld a, (ntc_rj_want)
			cp (hl)				; its place in the set
			jr nz, ntc_rj_skip
			or a
			jr z, ntc_rj_got
			push hl
			ld hl, (ntc_rj_set)
			or a
			sbc hl, de
			pop hl
			jr nz, ntc_rj_skip		; another build's
ntc_rj_got:
			ld (ntc_rj_set), de
			inc hl
			ld a, (hl)
			ld (ntc_rj_n), a		; ROMs in the set
			inc hl
			ld a, c
			or a				; NC
			ret
ntc_rj_skip:
			inc c
			ld a, c
			cp 32
			jr c, ntc_rj_next
			scf					; C: not there
			ret
ntc_rj_nf:
			ld hl, ntc_rj_tnf
			jr ntc_rj_fail
ntc_rj_part:				; a ROM of the set is missing: its number (1 = the main one)
			ld a, (ntc_rj_want)
			inc a
			ld e, a
			ld d, 0
			ld (ntc_rj_num), de
			ld hl, ntc_rj_tpt
			jr ntc_rj_fnum
ntc_rj_lacks:
			ld (ntc_rj_num), de
			ld hl, ntc_rj_tlk
ntc_rj_fnum:
			ld a, 1
			ld (ntc_rj_pn), a		; the number after the message
ntc_rj_fail:
			push hl
			ld bc, (ntc_rj_old)
			call #B918		; KL ROM DESELECT: the caller's selection again
			pop hl
			call ntc_rj_puts
			ld a, (ntc_rj_pn)
			or a
			jr z, ntc_rj_nl
			ld a, (ntc_rj_num + 1)
			call ntc_rj_hex
			ld a, (ntc_rj_num)
			call ntc_rj_hex
ntc_rj_nl:
			ld hl, ntc_rj_tnl
			call ntc_rj_puts
			ei
			call #BB06		; KM WAIT CHAR: a key first (a RUN" program's return resets the machine)
			di
			scf
			ret
ntc_rj_puts:				; HL = text, 0 ends; DE = its start
			ld d, h
			ld e, l
ntc_rj_pl:
			ld a, (hl)
			or a
			ret z
			call #BB5A		; TXT OUTPUT
			inc hl
			jr ntc_rj_pl
ntc_rj_hex:
			push af
			rrca
			rrca
			rrca
			rrca
			call ntc_rj_dig
			pop af
ntc_rj_dig:
			and 15
			add a, #90
			daa
			adc a, #40
			daa
			jp #BB5A
; End: the caller's ROM selection again, then back to the caller
ntc_rj_exit:
			ld bc, (ntc_rj_old)
			call #B918		; KL ROM DESELECT
			ret
ntc_rj_old:		dw 0			; the caller's ROM selection (C) and state (B)
ntc_rj_num:		dw 0
ntc_rj_pn:		db 0			; 1 = a number goes after the message
ntc_rj_want:	db 0			; the ROM of the set looked for
ntc_rj_n:		db 1			; ROMs in the set
ntc_rj_set:		dw 0			; the set's stamp
ntc_rj_slots:	ds 8			; each ROM's slot, the main one first
ntc_rj_sig:		db "NTC", 2, "CPC", 0	; the ROMs' NTC block
ntc_rj_sige:
ntc_rj_tnf:		db "ROM NTC CPC (NTCCPC.ROM) not found", 0
ntc_rj_tlk:		db "ROM NTC CPC too old: no routine #", 0
ntc_rj_tpt:		db "ROM NTCCPC<n>.ROM not found: n = #", 0
ntc_rj_tnl:		db 13, 10, "Press a key", 13, 10, 0

ntc_end:				; the end of the program (and of its file)
; arrays: after the program, not in its file - kw_bssinit checks they fit and clears them
ntc_bss		equ ntc_end
arr_boxes		equ ntc_bss + 0		; 6 bytes
arr_boxes_w		equ ntc_bss + 6		; 6 bytes
arr_boxes_h		equ ntc_bss + 12		; 6 bytes
ntc_bss_size	equ 18
ntc_free	equ ntc_bss + ntc_bss_size	; the first free byte (heap, Memory tables)
			SAVEAMSDOS "VBTEST3.BIN", ntc_start, ntc_end - ntc_start, ntc_start
